import{_ as s,c as t,o,ag as a}from"./chunks/framework.Ci10AEOF.js";const r="/docs-website/assets/global_scripts.CERydenH.png",u=JSON.parse('{"title":"Global Scripts","description":"Server-wide deploy, undeploy, preprocessor, and postprocessor scripts","frontmatter":{"title":"Global Scripts","description":"Server-wide deploy, undeploy, preprocessor, and postprocessor scripts"},"headers":[],"relativePath":"engine/global_scripts.md","filePath":"engine/global_scripts.md","lastUpdated":1793057853000}'),n={name:"engine/global_scripts.md"};function i(c,e,p,d,l,h){return o(),t("div",null,e[0]||(e[0]=[a('<h1 id="global-scripts" tabindex="-1">Global Scripts <a class="header-anchor" href="#global-scripts" aria-label="Permalink to &quot;Global Scripts&quot;">​</a></h1><p>Global scripts are server-wide deploy, undeploy, preprocessor, and postprocessor scripts. The deploy and undeploy scripts run once per deploy or undeploy operation. The preprocessor and postprocessor run for every message on every channel. The channel scripts of the same names belong to one channel.</p><h2 id="accessing-global-scripts" tabindex="-1">Accessing global scripts <a class="header-anchor" href="#accessing-global-scripts" aria-label="Permalink to &quot;Accessing global scripts&quot;">​</a></h2><ol><li>In the Administrator, navigate to <strong>Channels</strong> in the main menu</li><li>Click <strong>Edit Global Scripts</strong> in the task panel</li><li>The Global Scripts editor opens with a <strong>Script</strong> selector for Deploy, Undeploy, Preprocessor, and Postprocessor</li></ol><p><img src="'+r+`" alt="The Global Scripts editor showing the Deploy script, with the reference list on the right"></p><h2 id="available-objects" tabindex="-1">Available objects <a class="header-anchor" href="#available-objects" aria-label="Permalink to &quot;Available objects&quot;">​</a></h2><p>The engine builds a fresh scope for every run of a global script, and what it contains depends on the script type. The deploy and undeploy scripts run outside any channel, so nothing channel-scoped or message-scoped exists in them. The preprocessor and postprocessor run inside a channel for one message. The table lists each object, what it is, and which global scripts have it.</p><table tabindex="0"><thead><tr><th>Object</th><th>Description</th><th>Scripts</th></tr></thead><tbody><tr><td><code>globalMap</code></td><td>Server-wide variable map shared by every channel. A <code>get</code> followed by a <code>put</code> is not atomic</td><td>All</td></tr><tr><td><code>configurationMap</code></td><td>Server configuration key-value pairs</td><td>All</td></tr><tr><td><code>logger</code></td><td>Log4j logger named <code>deploy</code>, <code>undeploy</code>, <code>preprocessor</code>, or <code>postprocessor</code>, all at DEBUG in the shipped <code>log4j2.properties</code></td><td>All</td></tr><tr><td><code>router</code></td><td>VMRouter for sending messages to other channels</td><td>All</td></tr><tr><td><code>replacer</code></td><td>TemplateValueReplacer for variable substitution</td><td>All</td></tr><tr><td><code>DatabaseConnectionFactory</code></td><td>Factory for creating database connections. The engine never closes a connection a script opened</td><td>All</td></tr><tr><td><code>contextFactory</code></td><td>Access to the current JavaScript context, for example the custom resource IDs it uses</td><td>All</td></tr><tr><td><code>channelId</code></td><td>ID of the current channel</td><td>Preprocessor, postprocessor</td></tr><tr><td><code>channelName</code></td><td>Name of the current channel</td><td>Preprocessor, postprocessor</td></tr><tr><td><code>globalChannelMap</code></td><td>Per-channel map shared by every thread of that channel</td><td>Preprocessor, postprocessor</td></tr><tr><td><code>alerts</code></td><td>AlertSender for triggering alerts</td><td>Preprocessor, postprocessor</td></tr><tr><td><code>message</code></td><td>The raw message as a String in the preprocessor; an ImmutableMessage in the postprocessor</td><td>Preprocessor, postprocessor</td></tr><tr><td><code>connectorMessage</code></td><td>ImmutableConnectorMessage for the source connector</td><td>Preprocessor</td></tr><tr><td><code>connector</code></td><td>Name of the source connector</td><td>Preprocessor</td></tr><tr><td><code>destinationSet</code></td><td>DestinationSet for keeping the current message away from chosen destinations</td><td>Preprocessor</td></tr><tr><td><code>sourceMap</code></td><td>Source map</td><td>Preprocessor, postprocessor</td></tr><tr><td><code>connectorMap</code></td><td>Connector map of the source connector, writable</td><td>Preprocessor</td></tr><tr><td><code>channelMap</code></td><td>Channel map. Writable in the preprocessor, read-only in the postprocessor, where <code>put</code> throws <code>UnsupportedOperationException</code></td><td>Preprocessor, postprocessor</td></tr><tr><td><code>responseMap</code></td><td>Response map, writable in the preprocessor. In the postprocessor <code>put</code> does not throw: it writes to the merged copy the scope was built from, and the engine copies that map into the source connector&#39;s response map after this script runs</td><td>Preprocessor, postprocessor</td></tr><tr><td><code>response</code></td><td>The <code>Response</code> returned by the channel postprocessor, or null when it returned nothing</td><td>Postprocessor</td></tr><tr><td><code>RECEIVED</code>, <code>FILTERED</code>, <code>TRANSFORMED</code>, <code>SENT</code>, <code>QUEUED</code>, <code>ERROR</code>, <code>PENDING</code></td><td>Status constants for building a <code>Response</code></td><td>Postprocessor</td></tr></tbody></table><p>Every script is also compiled with the shorthand functions <code>$g</code> (globalMap), <code>$gc</code> (globalChannelMap), <code>$cfg</code> (configurationMap), <code>$c</code> (channelMap), <code>$co</code> (connectorMap), <code>$s</code> (sourceMap), and <code>$r</code> (responseMap). One argument gets a value, two arguments put one. Each shorthand needs its map to exist in the scope, so <code>$c</code> fails in the deploy and undeploy scripts.</p><h2 id="script-types" tabindex="-1">Script types <a class="header-anchor" href="#script-types" aria-label="Permalink to &quot;Script types&quot;">​</a></h2><h3 id="global-deploy-script" tabindex="-1">Global deploy script <a class="header-anchor" href="#global-deploy-script" aria-label="Permalink to &quot;Global deploy script&quot;">​</a></h3><p>Runs once per deploy operation, whatever set of channels is being deployed, before any channel deploy script. When the set includes a channel that is already deployed, the operation is a redeploy: the channel undeploy scripts run, then the global undeploy script, then the global deploy script, then the channel deploy scripts. An exception thrown here is logged and the deploy continues.</p><p>The sample runs in the global deploy scope: <code>globalMap</code>, <code>configurationMap</code>, <code>logger</code>, and the other server-wide objects from the table, but no <code>channelName</code>, <code>channelId</code>, or <code>globalChannelMap</code>, so a logger line here carries no channel prefix. It puts one value in the global map, where every channel script can read it afterwards with <code>globalMap.get</code> or <code>$g</code>, and writes a deploy-time line to the <code>deploy</code> logger.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">globalMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;facilityCode&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;HOSP1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">logger.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Global deploy: facilityCode = &#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> globalMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;facilityCode&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><h3 id="global-undeploy-script" tabindex="-1">Global undeploy script <a class="header-anchor" href="#global-undeploy-script" aria-label="Permalink to &quot;Global undeploy script&quot;">​</a></h3><p>Runs once at the end of every undeploy operation, after the channel undeploy scripts, and once inside every deploy operation that includes an already-deployed channel, before the global deploy script. Undeploying or redeploying a single channel runs it while every other channel stays deployed, so anything it removes from the global map or closes is gone for the channels still running, unless the global deploy script puts it back. Every channel is down when it runs on Redeploy All, at server shutdown, or when every channel is undeployed at once. Redeploy All is the path that also clears the global map between the undeploy and deploy phases when the server setting <strong>Clear global map on redeploy</strong> is Yes (the engine treats an unset value as Yes). The scope is the same as the global deploy scope. An exception thrown here is logged and the operation continues.</p><h3 id="global-preprocessor-script" tabindex="-1">Global preprocessor script <a class="header-anchor" href="#global-preprocessor-script" aria-label="Permalink to &quot;Global preprocessor script&quot;">​</a></h3><p>Runs once for every message on every channel, before the channel preprocessor, on the source connector message. The scope has <code>message</code> as the raw message String, <code>channelName</code>, <code>channelId</code>, <code>connectorMessage</code>, the writable <code>connectorMap</code>, <code>channelMap</code>, and <code>responseMap</code>, and the read-only <code>sourceMap</code>, from the table.</p><p>The string this script returns is the <code>message</code> the channel preprocessor receives. A script that ends without a <code>return</code> leaves the message unchanged. To change the message, return the modified string.</p><p>Do not log per message. The <code>preprocessor</code> logger is at DEBUG in the shipped configuration, so every line reaches <code>mirth.log</code> and the Server Log panel with no message context. A per-message fact belongs in the channel map, which is writable here and is shown with the message in the Message Browser. The sample records that it ran and returns the message unchanged.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">channelMap.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">put</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;globalPreprocessor&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ran&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> message;</span></span></code></pre></div><h3 id="global-postprocessor-script" tabindex="-1">Global postprocessor script <a class="header-anchor" href="#global-postprocessor-script" aria-label="Permalink to &quot;Global postprocessor script&quot;">​</a></h3><p>Runs once for every message on every channel, after the channel postprocessor. The scope has <code>message</code> as an ImmutableMessage, <code>channelId</code>, <code>response</code>, the status constants, and the maps from the table. <code>channelMap</code> is read-only here, so <code>channelMap.put</code> throws <code>UnsupportedOperationException</code>. It reads the maps, and it can return a <code>Response</code>.</p><p><code>response</code> is the <code>Response</code> the channel postprocessor returned, or null when that script returned nothing. Returning a <code>Response</code> from this script replaces it, returning nothing keeps it, and any other non-null value is wrapped as a <code>SENT</code> Response with that value as its message. The result is stored in the source connector&#39;s response map under the key <code>Postprocessor</code>, which the source connector sends back to the sender when its response is set to Postprocessor. <code>Response</code> is <code>com.mirth.connect.userutil.Response</code>, imported into every script scope, and <code>SENT</code> is one of the status constants in the postprocessor scope.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Response</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">SENT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;processed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="global-scripts-vs-channel-scripts" tabindex="-1">Global scripts vs. channel scripts <a class="header-anchor" href="#global-scripts-vs-channel-scripts" aria-label="Permalink to &quot;Global scripts vs. channel scripts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Global Scripts</th><th>Channel Scripts</th></tr></thead><tbody><tr><td><strong>Scope</strong></td><td>All channels on the server</td><td>Single channel only</td></tr><tr><td><strong>Execution order</strong></td><td>Global preprocessor runs first; global postprocessor runs last</td><td>Channel scripts run between global scripts</td></tr><tr><td><strong>Editing</strong></td><td>Edit Global Scripts view</td><td>Channel editor Scripts tab</td></tr></tbody></table><h3 id="execution-order" tabindex="-1">Execution order <a class="header-anchor" href="#execution-order" aria-label="Permalink to &quot;Execution order&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Global Preprocessor</span></span>
<span class="line"><span>  → Channel Preprocessor</span></span>
<span class="line"><span>    → Source Filter/Transformer</span></span>
<span class="line"><span>      → Destination chains (each destination: filter/transformer, send, response transformer)</span></span>
<span class="line"><span>    → Channel Postprocessor</span></span>
<span class="line"><span>  → Global Postprocessor</span></span></code></pre></div><h2 id="import-export" tabindex="-1">Import / export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import / export&quot;">​</a></h2><p>Global scripts can be imported and exported via the CLI:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>importscripts &quot;path&quot;</span></span>
<span class="line"><span>    Imports global scripts from file</span></span>
<span class="line"><span></span></span>
<span class="line"><span>exportscripts &quot;path&quot;</span></span>
<span class="line"><span>    Exports global scripts to file</span></span></code></pre></div><p>Scripts are also included when exporting the full server configuration (<code>exportcfg</code>).</p>`,33)]))}const b=s(n,[["render",i]]);export{u as __pageData,b as default};
